import type{PoolClient}from'pg';
export async function resolveLocation(c:PoolClient,scope:string,record:any):Promise<string|null>{let key:string|null=null;switch(scope){case'STATE':{const s=String(record.state??record.STATE??record.GeoFIPS??'').replace(/[^0-9]/g,'').padStart(2,'0').slice(-2);if(s)key=`US:STATE:${s}`;break}case'COUNTY':{const st=String(record.state??record.STATE??'').padStart(2,'0');const co=String(record.county??record.COUNTY??'').padStart(3,'0');if(st.trim()&&co.trim())key=`US:COUNTY:${st}${co}`;break}case'PLACE':{const st=String(record.state??record.STATE??'').padStart(2,'0');const pl=String(record.place??record.PLACE??'').padStart(5,'0');if(st.trim()&&pl.trim())key=`US:PLACE:${st}${pl}`;break}case'ZCTA':{const z=String(record['zip code tabulation area']??record.ZCTA5??record.zcta??'').padStart(5,'0');if(z.trim())key=`US:ZCTA:${z}`;break}case'POSTAL_CODE':{const z=String(record.ZIPCODE??record['zip code']??record.zip??'').padStart(5,'0');if(z.trim())key=`US:ZIP:${z}`;break}case'MSA':{const g=String(record.GeoFIPS??record.geo_fips??'').replace(/[^0-9]/g,'');if(g)key=`US:CBSA:${g}`;break}}if(!key)return null;const q=await c.query<{location_id:string}>(`SELECT location_id::text FROM zsl.certified_canonical_locations WHERE canonical_key=$1`,[key]);return q.rows[0]?.location_id??null}
